package cn.kaoyan.assistant;
import android.content.Context;import android.graphics.*;import android.media.ExifInterface;import android.net.Uri;import android.util.Base64;import org.json.JSONObject;import java.io.*;import java.util.*;
final class PhotoSupport {
 static JSONObject metadata(File f,String name)throws Exception{BitmapFactory.Options o=new BitmapFactory.Options();o.inJustDecodeBounds=true;BitmapFactory.decodeFile(f.getPath(),o);if(o.outWidth<=0||o.outHeight<=0)throw new IOException("无法读取这张图片，请选择JPEG或PNG照片");return new JSONObject().put("id",f.getName().substring(0,f.getName().lastIndexOf('.'))).put("path",f.getName()).put("name",name).put("title",name).put("kind","image").put("status","image").put("size",f.length()).put("created",new Date().toString()).put("subject","待确认").put("body","").put("version",1);}
 static File importPhoto(Context c,Uri uri)throws Exception{File dir=new File(c.getFilesDir(),"attachments");dir.mkdirs();String mime=c.getContentResolver().getType(uri);String ext="image/png".equals(mime)?"png":"image/webp".equals(mime)?"webp":"image/heic".equals(mime)||"image/heif".equals(mime)?"heic":"jpg";File f=new File(dir,"photo-"+UUID.randomUUID()+"."+ext);try{long size=0;try(InputStream in=c.getContentResolver().openInputStream(uri);OutputStream out=new FileOutputStream(f)){byte[] b=new byte[16384];int n;while((n=in.read(b))!=-1){size+=n;if(size>20*1024*1024)throw new IOException("图片超过20MB，请选择较小的照片");if(c.getFilesDir().getUsableSpace()<20*1024*1024)throw new IOException("设备可用空间不足");out.write(b,0,n);}}metadata(f,"识别原图."+ext);return f;}catch(Exception e){f.delete();throw e;}}
 static String dataUri(File file,int edge)throws Exception{BitmapFactory.Options bounds=new BitmapFactory.Options();bounds.inJustDecodeBounds=true;BitmapFactory.decodeFile(file.getPath(),bounds);if(bounds.outWidth<=0||bounds.outHeight<=0)throw new IOException("图片不可读");BitmapFactory.Options o=new BitmapFactory.Options();o.inSampleSize=1;while(Math.max(bounds.outWidth,bounds.outHeight)/o.inSampleSize>edge*2||(long)bounds.outWidth*bounds.outHeight/o.inSampleSize/o.inSampleSize>4000000L)o.inSampleSize*=2;Bitmap bitmap=BitmapFactory.decodeFile(file.getPath(),o);if(bitmap==null)throw new IOException("图片解码失败");try{int max=Math.max(bitmap.getWidth(),bitmap.getHeight());if(max>edge){Bitmap scaled=Bitmap.createScaledBitmap(bitmap,Math.max(1,bitmap.getWidth()*edge/max),Math.max(1,bitmap.getHeight()*edge/max),true);if(scaled!=bitmap){bitmap.recycle();bitmap=scaled;}}Matrix matrix=new Matrix();try{ExifInterface exif=new ExifInterface(file.getPath());switch(exif.getAttributeInt(ExifInterface.TAG_ORIENTATION,1)){case 2:matrix.setScale(-1,1);break;case 3:matrix.setRotate(180);break;case 4:matrix.setScale(1,-1);break;case 5:matrix.setRotate(90);matrix.postScale(-1,1);break;case 6:matrix.setRotate(90);break;case 7:matrix.setRotate(-90);matrix.postScale(-1,1);break;case 8:matrix.setRotate(-90);break;}}catch(IOException ignored){}if(!matrix.isIdentity()){Bitmap rotated=Bitmap.createBitmap(bitmap,0,0,bitmap.getWidth(),bitmap.getHeight(),matrix,true);if(rotated!=bitmap){bitmap.recycle();bitmap=rotated;}}ByteArrayOutputStream out=new ByteArrayOutputStream();bitmap.compress(Bitmap.CompressFormat.JPEG,82,out);if(out.size()>1500000){out.reset();bitmap.compress(Bitmap.CompressFormat.JPEG,60,out);}if(out.size()>2000000)throw new IOException("图片内容过大，请裁剪后重试");return "data:image/jpeg;base64,"+Base64.encodeToString(out.toByteArray(),Base64.NO_WRAP);}finally{bitmap.recycle();}}
}
